/* Territoria v0.3 · planeación (meta de abajo hacia arriba, plan, cronograma inverso, hitos, matriz), Brújula,
   tablero por fases, cuarto de guerra, eventos, gobierno de IA, chatbot anclado, segundo canal y reportes del Día E */
(function(){
const T=window.T,{C,D,S,H,fmt,pct}=T,D3=window.DATA3;
const sum=(a,k)=>a.reduce((s,x)=>s+(+x[k]||0),0),clone=x=>JSON.parse(JSON.stringify(x));
const K3=["objetivo","calcBU","metaDecl","brujula","plan","fases","hitos","eventos","decisiones","umbrales","segmentos","iaF","iaProv","faq","proveedores","reportes","cbPend","cb"];
K3.forEach(k=>{S[k]=T.ls(k,null)??clone(D3[k]??(k=="cbPend"||k=="cb"?[]:null))});
const save0=T.save;T.save=()=>{save0();K3.forEach(k=>T.lsSet(k,S[k]))};
const sub=def=>(T.ruta().split("?")[1]||def);
const tabs=(app,cur,l)=>`<div class="tabs">${l.map(([k,n])=>`<a class="btn sm ${cur==k?"on":""}" href="#/${app}?${k}">${n}</a>`).join("")}</div>`;
const dias=(a,b)=>Math.round((new Date(b+"T12:00:00")-new Date(a+"T12:00:00"))/864e5);
const addD=(iso,n)=>{const d=new Date(iso+"T12:00:00");d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const puedeDir=()=>["candidato","gerente"].includes(S.rol);
// =================== Hoja de ruta (fases 2 y 3) ===================
T.ROADMAP=[["VOLUNTARIOS","🙋","Voluntariado","Tareas, turnos, puerta a puerta e insignias sin premios.","Fase 2"],["EVENTOS","📅","Agenda y eventos completa","Agenda con tiempos entre municipios y asistencia por QR.","Fase 2"],["COMUNICACIONES","💬","Mensajes","SMS, correo y WhatsApp oficial solo con autorización.","Fase 2"],["ESCUCHA","👂","Escucha de redes","Menciones, alertas de bulos y de desinformación sobre el proceso electoral.","Fase 2"],["ENCUESTAS","📝","Encuestas","Internas anónimas y registro de encuestas externas con ficha técnica.","Fase 2"],["ADMIN","⚙️","Administración multi-campaña","Campañas aisladas, planes, alta y cierre con borrado.","Fase 2"],
 ["F2-PROP","📚","Banco de propuestas trazable","Cada propuesta con fuente, costo y dónde se presentó.","Fase 2"],["F2-AIDA","🧲","Embudo AIDA, manual de imagen y mapa de medios","Atención → interés → deseo → acción, con medios por provincia.","Fase 2"],["F2-DOFA","🧭","DOFA y mapa de actores","DOFA propia y de competidores solo con información pública.","Fase 2"],["F2-PULSO","💓","Pulso del equipo","Clima del equipo y articulación entre núcleo y base.","Fase 2"],["F2-AUT","🔏","Registro público de piezas oficiales","Huella y fecha de cada pieza para desmentir deepfakes.","Fase 2"],["F2-AUDIT","🧾","Autoauditoría de finanzas","Reglas de anomalías antes de Cuentas Claras.","Fase 2"],["F2-VPM","🛑","Violencia política digital contra mujeres","Alertas y casos con ruta de denuncia.","Fase 2"],["F2-EIA","⚖️","Evaluación de impacto de IA","Impacto previo, canal de impugnación y capacitación obligatoria.","Fase 2"],["F2-DIAE","🚦","Semáforo de preparación del Día E","Testigos capacitados e inventario de kits enlazado a gastos.","Fase 2"],["F2-CONF","🤝","Índice de confianza e imagen","Atributos deseados vs. medidos por encuesta.","Fase 2"],
 ["F3-PIL","🧪","Piloto territorial con control","Prueba de mensajes en un municipio antes de escalar.","Fase 3"],["F3-PANEL","📈","Panel longitudinal y capa de clima","Seguimiento por olas de encuesta.","Fase 3"],["F3-CMJ","🧑‍🎓","Elecciones de juventud (CMJ)","Requiere régimen de datos de menores (por verificar).","Fase 3"]];
// =================== Brújula de campaña ===================
T.brujulaCard=()=>{const b=S.brujula,a=b.acuses[S.rol],lei=a&&a.v==b.v,n=Object.values(b.acuses).filter(x=>x.v==b.v).length,tot=Object.keys(T.ROLES).length;
 return `<section class="card brujula" id="brujula" style="margin-top:14px"><div class="row b" style="flex-wrap:wrap"><h2>🧭 Brújula de campaña <span class="chip">v${b.v} · ${T.fecha(b.fecha)}</span></h2>${lei?`<span class="chip ok">✓ Leída por ti el ${T.fechaHora(a.t)}</span>`:`<button class="btn pri sm" id="bj-ok" type="button">✓ Confirmo que la leí</button>`}</div>
 <p><b>Objetivo:</b> ${H(b.objetivo)}</p><ol class="small">${b.prioridades.map(p=>`<li>${H(p)}</li>`).join("")}</ol><p class="legal small"><b>Mensaje básico:</b> «${H(b.mensaje)}»</p>
 ${puedeDir()?`<div class="row" style="flex-wrap:wrap"><button class="btn sm" id="bj-ed" type="button">✎ Editar (nueva versión)</button><button class="btn sm" id="bj-ac" type="button">Lecturas: ${n} de ${tot} roles</button></div>`:""}</section>`};
const ini0=T.V.inicio;T.V.inicio=()=>{const h=ini0();const i=h.indexOf("</section>")+10;return h.slice(0,i)+T.brujulaCard()+h.slice(i)};
T.onClick("#bj-ok",()=>{S.brujula.acuses[S.rol]={v:S.brujula.v,t:new Date().toISOString()};T.save();T.log("brujula.acuse",T.ROLES[S.rol].n+" leyó la Brújula v"+S.brujula.v);T.toast("✓ Lectura registrada");T.rerender()});
T.onClick("#bj-ac",()=>{const b=S.brujula;T.modal(`<h2>Lecturas de la Brújula v${b.v}</h2><div class="list small">${Object.entries(T.ROLES).map(([k,r])=>{const a=b.acuses[k];return `<div class="row b"><span>${H(r.n)}</span>${a&&a.v==b.v?`<span class="chip ok">✓ ${T.fechaHora(a.t)}</span>`:'<span class="chip wa">Pendiente</span>'}</div>`}).join("")}</div><p class="muted small">Cada nueva versión pide una nueva lectura a todos los roles y avisa a coordinadores y líderes (en producción, notificación en la app).</p>`)});
T.onClick("#bj-ed",()=>{const b=S.brujula;const m=T.modal(`<h2>Editar Brújula (v${b.v+1})</h2><label for="bj-obj">Objetivo</label><textarea id="bj-obj" rows="2">${H(b.objetivo)}</textarea>${b.prioridades.map((p,i)=>`<label for="bj-p${i}">Prioridad ${i+1}</label><input type="text" id="bj-p${i}" value="${H(p)}">`).join("")}<label for="bj-msg">Mensaje básico</label><textarea id="bj-msg" rows="2">${H(b.mensaje)}</textarea><button class="btn pri" id="bj-save" type="button" style="width:100%;margin-top:10px">Publicar nueva versión</button>`);
 m.querySelector("#bj-save").onclick=()=>{const q=s=>m.querySelector(s).value.trim();b.objetivo=q("#bj-obj");b.prioridades=[0,1,2].map(i=>q("#bj-p"+i));b.mensaje=q("#bj-msg");b.v++;b.fecha=T.hoyISO();b.acuses={};T.save();T.log("brujula.version","Brújula v"+b.v+" publicada por "+T.ROLES[S.rol].n);m.remove();T.toast("Brújula v"+b.v+" publicada: todos los roles deben leerla");T.rerender()}});
// =================== Estrategia ===================
const OBJ={ganar:["Ganar la curul","Meta = preferentes necesarios para entrar + 15 % de margen.","Votos verificados, posición en la lista y cobertura de testigos."],posicionarse:["Posicionarse","Meta = 60 % de lo necesario para entrar: quedar entre los primeros de la lista y crecer para la próxima.","Reconocimiento, red de líderes y votación por provincia."],participar:["Participar y construir base","Meta = superar la votación de referencia de 2023 en un 10 %, con énfasis en la red.","Líderes activos, voluntarios y registros con autorización."]};
T.metaObjetivo=()=>{const c=T.calc(),hist=sum(D.municipios,"v23"),nec=c.metaSugerida||Math.round(hist*1.2);return S.objetivo=="ganar"?nec:S.objetivo=="posicionarse"?Math.round(nec*.6):Math.round(hist*1.1)};
T.bottomUp=(o)=>{o=o||S.calcBU;const bruta=o.nodos*o.integrantes*o.contactos,est=Math.round(bruta*o.verificacion/100*o.conversion/100);return{bruta,est}};
T.inercial=()=>{const hoy=T.hoyISO(),sem=Math.max(0,dias(hoy,C.fechaEleccion)/7),base=T.calc().votosCand;return{base,sem:Math.round(sem),val:Math.round(base+D3.ritmoSemanal*sem*.6)}};
T.metaAlerta=()=>{const bu=T.bottomUp().est,hist=sum(D.municipios,"v23"),m=S.metaDecl.valor,u=S.umbrales.metaVsHist,al=[];
 if(m>bu*1.1)al.push(`la meta declarada (${fmt(m)}) supera lo que sostiene la red (${fmt(bu)} votos estimados de abajo hacia arriba)`);
 if(m>hist*u)al.push(`supera ${u}× la votación de referencia de 2023 (${fmt(hist)})`);return al};
const VE={};
VE.meta=()=>{const o=S.calcBU,bu=T.bottomUp(),mo=T.metaObjetivo(),hist=sum(D.municipios,"v23"),al=T.metaAlerta(),inr=T.inercial(),porNodo=o.integrantes*o.contactos*o.verificacion/100*o.conversion/100,falt=Math.max(0,Math.ceil((mo-bu.est)/Math.max(.01,porNodo)));
 const mx=Math.max(mo,bu.est,inr.val,S.metaDecl.valor,hist);const bar=(l,v,c)=>`<div><div class="row b small"><span>${l}</span><b>${fmt(v)}</b></div><div class="bar big"><i style="width:${Math.max(3,v/mx*100)}%;${c?"background:"+c:""}"></i></div></div>`;
 return `<div class="grid g3"><div class="card"><h2>1. Objetivo electoral</h2><div class="list">${Object.entries(OBJ).map(([k,[n,d]])=>`<label class="ck"><input type="radio" name="obj" value="${k}" id="ob-${k}" ${S.objetivo==k?"checked":""}> <span><b>${n}</b><br><span class="muted small">${d}</span></span></label>`).join("")}</div><p class="legal small"><b>El tablero prioriza:</b> ${OBJ[S.objetivo][2]}</p></div>
 <div class="card"><h2>2. Meta de abajo hacia arriba</h2><p class="muted small">Nodos (veredas, barrios, colegios) × integrantes por nodo × contactos por integrante.</p><div class="grid g2">${[["nodos","Nodos de la red"],["integrantes","Integrantes por nodo"],["contactos","Contactos por integrante"],["verificacion","Se verifican (%)"],["conversion","Votan (%)"]].map(([k,l])=>`<div><label for="bu-${k}">${l}</label><input type="number" id="bu-${k}" data-bu="${k}" value="${o[k]}" min="0"></div>`).join("")}</div>
 <div class="list small" id="bu-out" style="margin-top:10px"><div class="row b"><span>Contactos proyectados</span><b>${fmt(bu.bruta)}</b></div><div class="row b"><span>Votos estimados (verificados × conversión)</span><b id="bu-est">${fmt(bu.est)}</b></div><div class="row b"><span>Meta del objetivo «${OBJ[S.objetivo][0]}»</span><b id="bu-mo">${fmt(mo)}</b></div><div class="row b"><span>Nodos que faltan para la meta</span><b id="bu-falt">${fmt(falt)}</b></div></div><p class="muted small">Es una proyección, no votos seguros.</p></div>
 <div class="card"><h2>3. Meta declarada</h2><label for="md-val">Meta de votos preferentes (v${S.metaDecl.v})</label><input type="number" id="md-val" value="${S.metaDecl.valor}"><label for="md-just">Justificación del cambio</label><input type="text" id="md-just" placeholder="¿Por qué cambia la meta?"><button class="btn pri" id="md-save" type="button" style="margin-top:8px">Guardar meta</button>
 <div id="md-al" style="margin-top:10px">${al.length?`<p class="warn small">⚠ <b>Meta no sustentada:</b> ${al.map(H).join("; ")}.</p>`:'<p class="chip ok">✓ Meta sustentada por la red y el histórico</p>'}</div><p class="muted small">Referencia 2023: ${fmt(hist)} votos (ficticio; en producción, resultados oficiales de la Registraduría).</p></div></div>
 <div class="card" style="margin-top:14px" id="inercial"><h2>Escenario «si no intervenimos»</h2><p class="muted small">Si la campaña sigue al ritmo de las últimas 4 semanas (${fmt(D3.ritmoSemanal)} votos estimados por semana, con desgaste) durante las ${inr.sem} semanas que faltan, sin acciones nuevas.</p><div class="list">${bar("Si no intervenimos",inr.val,"var(--wa)")}${bar("Proyección de la red (abajo hacia arriba)",bu.est)}${bar("Meta del objetivo",mo,"linear-gradient(90deg,var(--ok),#0f9d76)")}${bar("Meta declarada",S.metaDecl.valor,"var(--ac2)")}</div>
 <p class="${inr.val<mo?"warn":"legal"} small" style="margin-top:8px">${inr.val<mo?`Brecha de <b>${fmt(mo-inr.val)}</b> votos frente a la meta: sin intervenir, el objetivo «${OBJ[S.objetivo][0]}» no se cumple.`:"Al ritmo actual se alcanza la meta."}</p></div>`};
VE.cifra=()=>{const h=VE._cifra();return h.replace(/^<h1>[^<]*<\/h1>/,"<h2>Meta y cifra repartidora</h2>")};
const TIPOS=["estrategia","objetivo","tactica","tarea"],TN={estrategia:"Estrategia",objetivo:"Objetivo",tactica:"Táctica",tarea:"Tarea"};
T.huerfanas=()=>S.plan.filter(x=>{if(x.tipo=="estrategia"||x.tipo=="objetivo")return false;let p=x,n=0;while(p&&n<6){p=S.plan.find(y=>y.id==p.padre);if(p&&p.tipo=="objetivo")return false;n++}return true});
VE.plan=()=>{const hu=T.huerfanas(),hoy=T.hoyISO();const nodo=(x,d)=>`<div class="pl pl-${x.tipo}" style="margin-left:${d*14}px"><span class="chip">${TN[x.tipo]}</span> <b>${H(x.t)}</b><br><span class="muted small">👤 ${H(x.resp||"Sin responsable")} ${x.rec?"· 💰 "+T.cop(x.rec):""} · ⏱ ${T.fecha(x.fin)} · ${H(x.estado)}${x.estado!="hecha"&&x.fin<hoy?' <span class="chip er">vencida</span>':""}</span></div>`+S.plan.filter(y=>y.padre==x.id).map(y=>nodo(y,d+1)).join("");
 return `<div class="grid g3"><div class="card" style="grid-column:span 2"><div class="row b" style="flex-wrap:wrap"><h2>Estrategia → objetivo → táctica → tarea</h2>${puedeDir()?'<button class="btn pri sm" id="pl-add" type="button">＋ Agregar</button>':""}</div><div class="list">${S.plan.filter(x=>x.tipo=="estrategia").map(x=>nodo(x,0)).join("")}</div></div>
 <div class="card"><h2>Tareas sin objetivo ${hu.length?`<span class="chip er" id="hu-n">${hu.length}</span>`:'<span class="chip ok" id="hu-n">0</span>'}</h2>${hu.length?`<p class="warn small">⚠ Estas actividades no sirven a ningún objetivo: consumen recursos sin aportar votos. Vincúlalas o descártalas.</p><div class="list small">${hu.map(x=>`<div class="item" style="cursor:default"><span style="flex:1"><b>${H(x.t)}</b><br><span class="muted">${H(x.resp)} · ${T.cop(x.rec||0)}</span></span>${puedeDir()?`<button class="btn sm" data-vinc="${x.id}" type="button">Vincular</button>`:""}</div>`).join("")}</div>`:'<p class="muted small">Todo lo que se hace sirve a un objetivo.</p>'}
 <h2 style="margin-top:12px">Recursos por objetivo</h2><div class="list small">${S.plan.filter(x=>x.tipo=="objetivo").map(o=>{const r=S.plan.filter(y=>{let p=y;while(p){if(p.padre==o.id)return true;p=S.plan.find(z=>z.id==p.padre)}return false});return `<div class="row b"><span>${H(o.t.slice(0,48))}…</span><b>${T.cop(sum(r,"rec"))}</b></div>`}).join("")}</div></div></div>`};
T.onClick("#pl-add",()=>{const m=T.modal(`<h2>Agregar al plan</h2><label for="pt">Nivel</label><select class="f" id="pt">${TIPOS.map(t=>`<option value="${t}" ${t=="tarea"?"selected":""}>${TN[t]}</option>`).join("")}</select><label for="ptt">Título</label><input type="text" id="ptt"><label for="pp">Depende de</label><select class="f" id="pp"></select><div class="grid g2"><div><label for="pr">Responsable</label><input type="text" id="pr"></div><div><label for="prc">Recursos (COP)</label><input type="number" id="prc" min="0" value="0"></div></div><label for="pf">Fecha de fin</label><input type="date" id="pf" value="${addD(T.hoyISO(),14)}"><button class="btn pri" id="pg" type="button" style="width:100%;margin-top:10px">Guardar</button>`);
 const q=s=>m.querySelector(s);const opts=()=>{const t=q("#pt").value,i=TIPOS.indexOf(t),up=TIPOS[i-1];q("#pp").innerHTML=(t=="estrategia"?"":"")+'<option value="">— Sin vincular —</option>'+(up?S.plan.filter(x=>x.tipo==up).map(x=>`<option value="${x.id}">${H(TN[x.tipo]+": "+x.t.slice(0,60))}</option>`).join(""):"")};q("#pt").onchange=opts;opts();
 q("#pg").onclick=()=>{const it={id:"N"+Date.now(),tipo:q("#pt").value,t:q("#ptt").value.trim(),padre:q("#pp").value||null,resp:q("#pr").value.trim(),rec:+q("#prc").value||0,fin:q("#pf").value,estado:"pendiente"};
  if(!it.t){T.toast("Escribe el título");return}if(["tactica","tarea"].includes(it.tipo)&&!it.resp){T.toast("Las tácticas y tareas necesitan responsable");return}
  T.accion("plan.agregar",TN[it.tipo]+": "+it.t+(it.padre?"":" (sin vincular)"),()=>{S.plan.push(it);T.save()});if(!it.padre&&["tactica","tarea"].includes(it.tipo))T.toast("⚠ Quedó sin objetivo: aparece en «Tareas sin objetivo»");m.remove();T.rerender()}});
T.onClick("[data-vinc]",t=>{const x=S.plan.find(y=>y.id==t.dataset.vinc);const up=x.tipo=="tarea"?"tactica":"objetivo";const m=T.modal(`<h2>Vincular</h2><p class="small">${H(x.t)}</p><label for="vs">${up=="tactica"?"Táctica":"Objetivo"}</label><select class="f" id="vs">${S.plan.filter(y=>y.tipo==up).map(y=>`<option value="${y.id}">${H(y.t)}</option>`).join("")}</select><button class="btn pri" id="vg" type="button" style="width:100%;margin-top:10px">Vincular</button>`);
 m.querySelector("#vg").onclick=()=>{const p=m.querySelector("#vs").value;T.accion("plan.vincular",x.t+" → "+S.plan.find(y=>y.id==p).t,()=>{x.padre=p;T.save()});m.remove();T.rerender()}});
T.fasesCalc=()=>{const f=S.fases,fin=C.fechaEleccion,movIni=addD(fin,-f.mov*7),conIni=addD(movIni,-f.con*7);const tope=C.finanzas.topeLista/C.finanzas.candidatosLista;
 const L=[["Visibilidad",f.inicio,addD(conIni,-1),f.pv,"Que me conozcan: reconocimiento ≥ 40 % en la encuesta interna"],["Contacto",conIni,addD(movIni,-1),f.pc,"Registros autorizados y verificados ≥ 70 % de la meta"],["Cierre",movIni,fin,f.pm,"Confirmaciones del propio titular, voluntariado activo y testigos en el 100 % de las mesas prioritarias"]].map(([n,a,b,p,o])=>({n,a,b,p,o,pres:Math.round(tope*p/100),ejec:sum(S.gastos.filter(g=>g.fecha>=a&&g.fecha<=b),"valor")}));
 const hoy=T.hoyISO();L.forEach(x=>x.actual=hoy>=x.a&&hoy<=x.b);return{L,ok:conIni>f.inicio&&f.pv+f.pc+f.pm==100,suma:f.pv+f.pc+f.pm,conIni,movIni}};
VE.crono=()=>{const f=S.fases,r=T.fasesCalc(),tot=dias(f.inicio,C.fechaEleccion),pos=d=>Math.max(0,Math.min(100,dias(f.inicio,d)/tot*100));
 return `<div class="grid g3"><div class="card"><h2>Planificador inverso desde el Día E</h2><p class="muted small">Se construye hacia atrás desde el ${T.fecha(C.fechaEleccion)}. Si mueves una fase, todo se recalcula.</p><div class="grid g2"><div><label for="rp-ini">Inicio de campaña</label><input type="date" id="rp-ini" data-rp="inicio" value="${f.inicio}"></div><div><label for="rp-mov">Semanas de Cierre</label><input type="number" id="rp-mov" data-rp="mov" value="${f.mov}" min="1"></div><div><label for="rp-con">Semanas de Contacto</label><input type="number" id="rp-con" data-rp="con" value="${f.con}" min="1"></div><div></div>${[["pv","Presupuesto Visibilidad (%)"],["pc","Presupuesto Contacto (%)"],["pm","Presupuesto Cierre (%)"]].map(([k,l])=>`<div><label for="rp-${k}">${l}</label><input type="number" id="rp-${k}" data-rp="${k}" value="${f[k]}" min="0" max="100"></div>`).join("")}</div>
 ${r.ok?"":`<p class="warn small" id="rp-al">⚠ ${r.suma!=100?"Los porcentajes de presupuesto suman "+r.suma+" % (deben sumar 100 %).":"El cronograma no cabe: la fase de Contacto empezaría antes del inicio de la campaña."}</p>`}</div>
 <div class="card" style="grid-column:span 2"><h2>Línea de tiempo</h2><div class="tl"><div class="tlbar">${r.L.map((x,i)=>`<div class="tlf tlf${i}" style="left:${pos(x.a)}%;width:${pos(x.b)-pos(x.a)}%"><span>${x.n}</span></div>`).join("")}<div class="tlhoy" style="left:${pos(T.hoyISO())}%" title="Hoy"><span>Hoy</span></div>${S.hitos.map(h=>`<i class="tlh ${valHito(h)?"bad":""}" style="left:${pos(h.f)}%" title="${H(h.n)} · ${h.f}"></i>`).join("")}</div></div>
 <div class="tw" style="margin-top:12px"><table><tr><th>Fase</th><th>Fechas</th><th>Criterio de salida</th><th>Presupuesto</th><th>Ejecutado</th></tr>${r.L.map(x=>`<tr${x.actual?' style="font-weight:700"':""}><td>${x.n}${x.actual?' <span class="chip ok">actual</span>':""}</td><td class="small">${T.fecha(x.a)} – ${T.fecha(x.b)}</td><td class="small">${H(x.o)}</td><td>${T.cop(x.pres)}</td><td>${T.cop(x.ejec)} ${x.ejec>x.pres?'<span class="chip er">excede</span>':""}</td></tr>`).join("")}</table></div><p class="muted small">Presupuesto sobre el tope individual (ficticio). La fase actual se resalta en el tablero.</p></div></div>`};
const REG={inscripcion:["Dentro del periodo de inscripción",h=>h.f>=C.calendario.inscripcionDesde&&h.f<=C.calendario.inscripcionHasta],propEspacio:["Desde el inicio de propaganda en espacio público ("+C.calendario.propagandaEspacioPublico+")",h=>h.f>=C.calendario.propagandaEspacioPublico],propMedios:["Desde el inicio de propaganda en medios y redes ("+C.calendario.propagandaMedios+", Ley 1475 art. 35)",h=>h.f>=C.calendario.propagandaMedios],antesEleccion:["Antes del día de la elección",h=>h.f<C.fechaEleccion],cierre:["Antes del día de la elección; sin actos públicos el día E (por verificar)",h=>h.f<C.fechaEleccion],fija:["Fecha legal fija",h=>true]};
function valHito(h){const r=REG[h.regla];return r&&!r[1](h)?"No cumple: "+r[0]:null}
T.valHito=valHito;
VE.hitos=()=>{const bad=S.hitos.filter(valHito);return `<div class="card"><div class="row b" style="flex-wrap:wrap"><h2>Catálogo de hitos</h2>${bad.length?`<span class="chip er" id="hi-n">${bad.length} hito(s) incumplen plazos legales</span>`:'<span class="chip ok" id="hi-n">Todos los hitos cumplen los plazos</span>'}</div>
 <div class="tw"><table><tr><th>Hito</th><th>Tipo</th><th>Fecha</th><th>Regla legal</th><th>Estado</th></tr>${S.hitos.slice().sort((a,b)=>a.f<b.f?-1:1).map(h=>{const v=valHito(h);return `<tr><td><b>${H(h.n)}</b></td><td><span class="chip">${h.tipo=="legal"?"Legal":"Propio"}</span></td><td>${h.fija?T.fecha(h.f)+" 🔒":`<input type="date" data-hito="${h.id}" value="${h.f}" aria-label="Fecha de ${H(h.n)}">`}</td><td class="small">${H(REG[h.regla][0])}</td><td>${v?`<span class="chip er">⛔ ${H(v)}</span>`:'<span class="chip ok">✓</span>'}</td></tr>`}).join("")}</table></div>
 ${puedeDir()?`<div class="row" style="flex-wrap:wrap;margin-top:10px"><input type="text" id="hn-n" placeholder="Nuevo hito" aria-label="Nombre del hito" style="flex:1;min-width:180px"><input type="date" id="hn-f" aria-label="Fecha" value="${addD(T.hoyISO(),7)}"><select class="btn" id="hn-r" aria-label="Regla">${Object.entries(REG).filter(([k])=>!["fija","inscripcion"].includes(k)).map(([k,[l]])=>`<option value="${k}">${H(l.split(" (")[0])}</option>`).join("")}</select><button class="btn pri" id="hn-add" type="button">＋ Agregar hito</button></div>`:""}
 <p class="muted small" style="margin-top:8px">Fechas legales del calendario de la Registraduría (por verificar). Las fechas que incumplen una regla no se pueden guardar.</p></div>`};
const segSens=c=>/opini[oó]n pol|religi|etnia|salud/i.test(c),segProh=c=>/emocional|psicol/i.test(c);
VE.matriz=()=>`<div class="card"><div class="row b" style="flex-wrap:wrap"><h2>Matriz segmento → mensaje → canal → indicador</h2>${puedeDir()||S.rol=="cm"?'<button class="btn pri sm" id="sg-add" type="button">＋ Segmento</button>':""}</div>
<div class="tw"><table><tr><th>Segmento</th><th>Mensaje</th><th>Canal</th><th>Indicador</th><th></th></tr>${S.segmentos.map(s=>`<tr><td><b>${H(s.n)}</b><br>${s.tipo=="opositor"?'<span class="chip wa">🔒 Solo agregado</span>':`<span class="chip">${s.tipo=="interno"?"Interno":s.tipo=="propio"?"Personas con autorización":"Agregado"}</span>`}</td><td class="small">${H(s.mensaje)}</td><td class="small">${H(s.canal)}</td><td class="small">${s.tipo=="opositor"?H(s.indicador):`${H(s.indicador)}: <b>${fmt(s.actual)}</b> / ${fmt(s.meta)}<div class="bar"><i style="width:${Math.min(100,pct(s.actual,s.meta))}%"></i></div>`}</td><td><button class="btn sm" data-ficha="${s.id}" type="button">Ficha de transparencia</button>${s.tipo=="opositor"?'<br><span class="muted small">Sin fichas ni listas de personas</span>':""}</td></tr>`).join("")}</table></div>
<p class="legal small" style="margin-top:8px">Los votantes de otras listas solo se analizan en agregado con resultados públicos por mesa: no se crean fichas, etiquetas ni listas de «opositores» (Ley 1581, art. 5; Circular SIC 002/2026, instr. 7, por verificar). Prohibido segmentar por miedo, odio, vulnerabilidad o rasgos psicológicos.</p></div>`;
T.onClick("#sg-add",()=>{const CR=["Territorio (provincia o municipio)","Rango de edad (agregado del censo)","Interés declarado en el registro","Encuesta interna anónima","Opinión política declarada por el titular","Religión, etnia o salud (dato sensible)","Rasgo emocional o psicológico (miedo, odio, vulnerabilidad)"];
 const m=T.modal(`<h2>Nuevo segmento</h2><label for="sg-n">Nombre</label><input type="text" id="sg-n"><label>Criterios</label>${CR.map((c,i)=>`<label class="ck"><input type="checkbox" data-cr="${H(c)}" id="sgc${i}"> ${H(c)}</label>`).join("")}<label class="ck"><input type="checkbox" id="sg-aut"><span> Los titulares dieron <b>autorización previa, expresa e informada</b> para usar ese dato con esta finalidad</span></label><label for="sg-m">Mensaje</label><input type="text" id="sg-m"><label for="sg-c">Canal</label><select class="f" id="sg-c">${["WhatsApp Business oficial con autorización","SMS con autorización","Redes (orgánico)","Puerta a puerta","Eventos"].map(x=>`<option>${x}</option>`).join("")}</select><label for="sg-i">Indicador</label><input type="text" id="sg-i" value="Registros con autorización"><div id="sg-err"></div><button class="btn pri" id="sg-g" type="button" style="width:100%;margin-top:10px">Guardar</button>`);
 const q=s=>m.querySelector(s);q("#sg-g").onclick=()=>{const cr=[...m.querySelectorAll("[data-cr]")].filter(x=>x.checked).map(x=>x.dataset.cr),n=q("#sg-n").value.trim();if(!n||!cr.length){T.toast("Nombre y al menos un criterio");return}
  if(cr.some(segProh)){q("#sg-err").innerHTML='<p class="warn small">⛔ Prohibido segmentar por miedo, odio, vulnerabilidad o rasgos psicológicos.</p>';T.log("segmento.bloqueo",n+": criterio psicológico/emocional");return}
  if(cr.some(segSens)&&!q("#sg-aut").checked){q("#sg-err").innerHTML='<p class="warn small">⛔ No se segmenta por opinión política ni por datos sensibles sin autorización explícita del titular para esta finalidad (Circular SIC 002/2026, instr. 7; Ley 1581, art. 6, por verificar).</p>';T.log("segmento.bloqueo",n+": dato sensible sin autorización");return}
  const s={id:"S"+Date.now(),n,tipo:cr.some(c=>/declarad|autoriz/.test(c))?"propio":"agregado",criterios:cr,mensaje:q("#sg-m").value.trim()||"Por definir",canal:q("#sg-c").value,indicador:q("#sg-i").value,meta:100,actual:0,sensible:cr.some(segSens),aut:q("#sg-aut").checked};
  T.accion("segmento.crear",n+" · "+cr.join(", "),()=>{S.segmentos.push(s);T.save()});m.remove();T.rerender()}});
T.fichaTxt=s=>`FICHA DE TRANSPARENCIA DE SEGMENTACIÓN\nCampaña: ${C.campana}\nSegmento: ${s.n}\nCriterios: ${s.criterios.join("; ")}\nDatos usados: ${s.tipo=="opositor"?"resultados electorales públicos por mesa (agregados)":s.tipo=="agregado"?"datos agregados por territorio, sin identificar personas":"datos que el titular entregó en su registro, con autorización por canal"}\nFuente: ${s.tipo=="opositor"?"Registraduría (resultados oficiales)":"registro propio de la campaña con aviso de privacidad "+C.privacidad.version}\nLógica: se agrupa por los criterios indicados; no hay puntajes individuales ni inferencias de opinión política.\nUso de IA: ${s.ia?"sí":"no"} (la IA no usa datos sensibles)\nDatos sensibles: ${s.sensible?"sí, con autorización explícita":"no"}\nCanal: ${s.canal}\n¿Por qué recibo esto?: Recibes este mensaje porque ${s.tipo=="opositor"?"es comunicación pública general de la campaña":"autorizaste el canal «"+s.canal+"» y "+s.criterios[0].toLowerCase()+" coincide con este grupo"}. Puedes retirar tu autorización en ${C.privacidad.canal}.\nReferencia: Circular Externa SIC 002 de 2026, instr. 8 (por verificar).\n`;
T.onClick("[data-ficha]",t=>{const s=S.segmentos.find(x=>x.id==t.dataset.ficha);const m=T.modal(`<h2>Ficha de transparencia</h2><pre class="small" style="white-space:pre-wrap">${H(T.fichaTxt(s))}</pre><button class="btn pri" id="ft-dl" type="button">⬇ Descargar ficha</button>`,{wide:true});m.querySelector("#ft-dl").onclick=()=>{T.descargar("ficha_transparencia_"+s.id+".txt",T.fichaTxt(s));T.log("segmento.ficha","Ficha de transparencia: "+s.n)}});
VE._cifra=T.V.ESTRATEGIA;const aCifra=T.after.ESTRATEGIA;
T.V.ESTRATEGIA=()=>{const t=sub("meta");return `<h1>Estrategia</h1><p class="sub">Objetivo, meta sustentada, plan con responsables, cronograma desde el Día E y a quién le hablamos.</p>${tabs("ESTRATEGIA",t,[["meta","🎯 Objetivo y meta"],["cifra","🧮 Cifra repartidora"],["plan","🗂 Plan"],["crono","⏳ Cronograma"],["hitos","📍 Hitos"],["matriz","🧩 Segmentos y mensajes"]])}<div style="margin-top:12px">${(VE[t]||VE.meta)()}</div>`};
T.after.ESTRATEGIA=()=>{const t=sub("meta");
 if(t=="cifra")aCifra();
 if(t=="meta"){document.querySelectorAll("[name=obj]").forEach(r=>r.onchange=()=>{S.objetivo=r.value;T.save();T.log("estrategia.objetivo","Objetivo: "+OBJ[r.value][0]);T.rerender()});
  document.querySelectorAll("[data-bu]").forEach(i=>i.onchange=()=>{S.calcBU[i.dataset.bu]=Math.max(0,+i.value||0);T.save();T.rerender()});
  T.$("#md-save").onclick=()=>{const v=+T.$("#md-val").value||0,j=T.$("#md-just").value.trim();if(v==S.metaDecl.valor){T.toast("La meta no cambió");return}if(j.length<15){T.toast("Explica el cambio (mínimo 15 caracteres): la meta queda versionada");return}
   S.metaDecl.hist.push({v:S.metaDecl.v,valor:S.metaDecl.valor,just:S.metaDecl.just});S.metaDecl={v:S.metaDecl.v+1,valor:v,just:j,hist:S.metaDecl.hist};T.save();T.log("estrategia.meta","Meta v"+S.metaDecl.v+": "+fmt(v)+" · "+j);T.toast("Meta v"+S.metaDecl.v+" guardada");T.rerender()}}
 if(t=="crono")document.querySelectorAll("[data-rp]").forEach(i=>i.onchange=()=>{const k=i.dataset.rp;S.fases[k]=k=="inicio"?i.value:Math.max(0,+i.value||0);T.save();T.log("estrategia.cronograma","Cronograma recalculado ("+k+")");T.rerender()});
 if(t=="hitos"){document.querySelectorAll("[data-hito]").forEach(i=>i.onchange=()=>{const h=S.hitos.find(x=>x.id==i.dataset.hito),prev=h.f;h.f=i.value;const v=valHito(h);if(v){h.f=prev;i.value=prev;T.toast("⛔ "+v);T.log("estrategia.hito.bloqueo",h.n+" en "+i.value+": "+v);return}T.save();T.log("estrategia.hito",h.n+" → "+h.f);T.toast("✓ Hito actualizado");T.rerender()});
  const a=T.$("#hn-add");a&&(a.onclick=()=>{const h={id:"H"+Date.now(),n:T.$("#hn-n").value.trim(),f:T.$("#hn-f").value,tipo:"propio",regla:T.$("#hn-r").value};if(!h.n){T.toast("Escribe el nombre del hito");return}const v=valHito(h);if(v){T.toast("⛔ "+v);T.log("estrategia.hito.bloqueo",h.n+": "+v);return}T.accion("estrategia.hito",h.n+" · "+h.f,()=>{S.hitos.push(h);T.save()});T.rerender()})}};
// =================== Tablero: fases, cuarto de guerra, eventos ===================
T.embudoFases=()=>{const pub=S.piezas.filter(p=>p.estado=="Publicada"),alc=sum(pub,"alcance"),asis=sum(S.eventos,"real"),regC=sum(S.piezas,"registros")+Math.round(asis*.15),ver=sum(D.municipios,"verificados"),conf=sum(D.municipios,"confirmados"),vol=D3.kpiFases.voluntarios,test=S.mesas.filter(m=>m.testigo).length,u=S.umbrales;
 const F=[["Visibilidad",[["Alcance digital",fmt(alc)],["Asistentes a eventos",fmt(asis)],["Reconocimiento (encuesta interna)",D3.kpiFases.reconocimiento+" %"]]],["Contacto",[["Registros con autorización desde contenido y eventos",fmt(regC)],["Simpatizantes verificados",fmt(ver)],["Confirmados por contacto",fmt(conf)]]],["Cierre",[["Voluntarios activos",fmt(vol)],["Mesas con testigo",pct(test,S.mesas.length)+" %"],["Votos estimados",fmt(T.calc().votosCand)]]]];
 const al=[],rc=alc?regC/alc*100:0,rv=ver?vol/ver*100:0;
 if(rc<u.espectaculo)al.push(["Espectáculo",`Mucha visibilidad y poco contacto: solo ${rc.toFixed(2)} % del alcance se convierte en registros con autorización (umbral ${u.espectaculo} %).`]);
 if(rv<u.simpatia)al.push(["Simpatía sin votos",`Muchos verificados y pocos voluntarios: ${rv.toFixed(1)} % (umbral ${u.simpatia} %). Sin voluntariado activo, la simpatía no se convierte en participación.`]);
 return{F,al}};
T.eventosDesvio=()=>S.eventos.filter(e=>e.real!=null&&(e.meta-e.real)/e.meta*100>S.umbrales.desvioEvento);
T.agendaGuerra=()=>{const hoy=T.hoyISO(),r=T.fasesCalc(),fa=r.L.find(x=>x.actual),e=T.embudoFases(),venc=S.plan.filter(x=>x.estado!="hecha"&&x.fin<hoy),hu=T.huerfanas(),ev=T.eventosDesvio().filter(x=>!x.causa),hb=S.hitos.filter(valHito),ma=T.metaAlerta();
 const it=[["Fase actual",fa?fa.n+" ("+T.fecha(fa.a)+" – "+T.fecha(fa.b)+"). Criterio de salida: "+fa.o:"Fuera del cronograma"]];
 e.al.forEach(a=>it.push(["Desbalance: "+a[0],a[1]]));venc.forEach(x=>it.push(["Tarea vencida",x.t+" · "+x.resp]));hu.length&&it.push(["Tareas sin objetivo",hu.length+": "+hu.map(x=>x.t).join("; ")]);ev.forEach(x=>it.push(["Evento sin causa registrada",x.n+": "+x.real+" de "+x.meta]));hb.forEach(h=>it.push(["Hito fuera de plazo",h.n]));ma.length&&it.push(["Meta no sustentada",ma.join("; ")]);return it};
const VT={};
VT.fases=()=>{const e=T.embudoFases(),r=T.fasesCalc();return `<div class="grid g3">${e.F.map(([n,k],i)=>`<div class="card fase${r.L[i].actual?" actual":""}"><h2>${i+1}. ${n} ${r.L[i].actual?'<span class="chip ok">fase actual</span>':""}</h2><div class="list small">${k.map(([l,v])=>`<div class="row b"><span>${l}</span><b>${v}</b></div>`).join("")}</div><p class="muted small">${T.fecha(r.L[i].a)} – ${T.fecha(r.L[i].b)}</p></div>`).join("")}</div>
 <div class="card" style="margin-top:14px"><h2>Alertas de desbalance</h2>${e.al.length?e.al.map(([t,d])=>`<p class="warn small" data-alerta="${H(t)}">⚠ <b>${t}:</b> ${H(d)}</p>`).join(""):'<p class="chip ok">Embudo equilibrado</p>'}<p class="legal small">Visibilidad sin contacto es espectáculo; contacto sin voluntariado activo es simpatía que no se convierte en participación. Lo digital no es voto.</p>
 <div class="grid g2"><div><label for="um-esp">Umbral «espectáculo» (% del alcance)</label><input type="number" id="um-esp" step="0.1" value="${S.umbrales.espectaculo}"></div><div><label for="um-sim">Umbral «simpatía» (% voluntarios / verificados)</label><input type="number" id="um-sim" step="0.5" value="${S.umbrales.simpatia}"></div></div></div>`};
const lunes=iso=>{const d=new Date(iso+"T12:00:00");d.setDate(d.getDate()-((d.getDay()+6)%7));return d.toISOString().slice(0,10)};
VT.guerra=()=>{const sem=lunes(T.hoyISO()),ag=T.agendaGuerra(),dec=S.decisiones,g={};dec.forEach(d=>(g[d.sem]=g[d.sem]||[]).push(d));
 return `<div class="grid g2"><div class="card"><h2>Cuarto de guerra · semana del ${T.fecha(sem)}</h2><p class="muted small">Agenda generada automáticamente para la revisión de los lunes.</p><ol class="small" id="ag-list">${ag.map(([t,d])=>`<li><b>${H(t)}:</b> ${H(d)}</li>`).join("")}</ol></div>
 <div class="card"><h2>Bitácora de decisiones</h2>${puedeDir()?`<label for="dc-txt">Decisión</label><input type="text" id="dc-txt" placeholder="Qué se decidió"><div class="grid g2"><div><label for="dc-resp">Responsable</label><input type="text" id="dc-resp"></div><div><label for="dc-f">Fecha límite</label><input type="date" id="dc-f" value="${addD(T.hoyISO(),7)}"></div></div><button class="btn pri" id="dc-add" type="button" style="margin-top:8px">Registrar decisión</button>`:'<p class="muted small">Solo candidata y gerencia registran decisiones.</p>'}
 <div class="list small" id="dc-list" style="margin-top:12px">${Object.keys(g).sort().reverse().map(s=>`<div><b>Semana del ${T.fecha(s)}</b>${g[s].map(d=>`<div class="row b"><span>• ${H(d.t)}<br><span class="muted">${H(d.resp)} · hasta ${T.fecha(d.f)} · ${H(d.por)}</span></span></div>`).join("")}</div>`).join("")}</div><p class="muted small">Cada decisión queda en el registro a prueba de alteraciones.</p></div></div>`};
VT.eventos=()=>`<div class="card"><h2>Meta de asistencia vs. asistencia real</h2><div class="tw"><table><tr><th>Evento</th><th>Fecha</th><th>Meta</th><th>Real</th><th>Desvío</th><th>Causa y corrección</th></tr>${S.eventos.map(e=>{const d=e.real==null?null:Math.round((e.real-e.meta)/e.meta*100),mal=d!=null&&-d>S.umbrales.desvioEvento;return `<tr><td><b>${H(e.n)}</b><br><span class="muted small">${H(e.tipo)} · ${H(e.mun)}</span></td><td class="small">${T.fecha(e.f)}</td><td>${fmt(e.meta)}</td><td>${e.real==null?"—":fmt(e.real)}</td><td>${d==null?"":`<span class="chip ${mal?"er":d<0?"wa":"ok"}">${d>0?"+":""}${d} %</span>`}</td><td class="small">${e.causa?`<b>${H(e.causa)}</b><br>${H(e.corr)}`:mal?`<button class="btn sm danger" data-evc="${e.id}" type="button">Registrar causa</button>`:""}</td></tr>`}).join("")}</table></div><p class="muted small">Alerta cuando la asistencia queda más de ${S.umbrales.desvioEvento} % por debajo de la meta; la causa pasa a la revisión semanal. Sin refrigerios ni regalos condicionados a la asistencia.</p></div>`;
T.onClick("[data-evc]",t=>{const e=S.eventos.find(x=>x.id==t.dataset.evc);const m=T.modal(`<h2>${H(e.n)}</h2><p class="small">Meta ${e.meta}, llegaron ${e.real}.</p><label for="ec-c">Causa</label><select class="f" id="ec-c">${["Convocatoria tardía","Lugar o fecha inadecuados","Coincidió con otro evento","Clima","Mensaje poco claro","Meta inflada","Otra"].map(x=>`<option>${x}</option>`).join("")}</select><label for="ec-k">Corrección</label><input type="text" id="ec-k" placeholder="Qué haremos distinto"><button class="btn pri" id="ec-g" type="button" style="width:100%;margin-top:10px">Guardar</button>`);
 m.querySelector("#ec-g").onclick=()=>{const k=m.querySelector("#ec-k").value.trim();if(!k){T.toast("Escribe la corrección");return}T.accion("evento.causa",e.n+": "+m.querySelector("#ec-c").value,()=>{e.causa=m.querySelector("#ec-c").value;e.corr=k;T.save()});m.remove();T.rerender()}});
const tab0=T.V.TABLERO,aTab0=T.after.TABLERO;
T.V.TABLERO=()=>{const t=sub("resumen");const tb=tabs("TABLERO",t,[["resumen","📊 Resumen"],["fases","🪜 Fases"],["guerra","🛡 Cuarto de guerra"],["eventos","📅 Eventos"]]);
 if(t=="resumen"){const h=tab0();const i=h.indexOf("</p>")+4;return h.slice(0,i)+tb+'<div style="height:12px"></div>'+h.slice(i)}
 return `<h1>Tablero de la candidata</h1><p class="sub">${t=="fases"?"Embudo Visibilidad → Contacto → Cierre.":t=="guerra"?"Revisión semanal con decisiones registradas.":"¿Llegó la gente que esperábamos?"}</p>${tb}<div style="margin-top:12px">${VT[t]()}</div>`};
T.after.TABLERO=()=>{const t=sub("resumen");if(t=="resumen"){aTab0&&aTab0();return}
 if(t=="fases")["#um-esp","#um-sim"].forEach(s=>T.$(s).onchange=()=>{S.umbrales[s=="#um-esp"?"espectaculo":"simpatia"]=+T.$(s).value;T.save();T.rerender()});
 if(t=="guerra"){const b=T.$("#dc-add");b&&(b.onclick=()=>{const d={sem:lunes(T.hoyISO()),t:T.$("#dc-txt").value.trim(),resp:T.$("#dc-resp").value.trim(),f:T.$("#dc-f").value,por:T.ROLES[S.rol].n};if(!d.t||!d.resp){T.toast("Escribe la decisión y el responsable");return}T.accion("guerra.decision",d.t+" · "+d.resp,()=>{S.decisiones.push(d);T.save()});T.rerender()})}};
// =================== Gobierno de IA, chatbot ===================
T.IA.FUN={contenido:["Generación de contenido","Borradores de publicaciones, guiones, hilos e ideas","Tema, tono, red y territorio (sin datos personales)","Medio"],propuestas:["Propuestas y programa","Ejes de programa con diagnóstico, metas e indicadores","Documentos públicos e insumos del equipo","Medio"],documentos:["Análisis de documentos","Resumen, problemas, cifras y oportunidades de documentos públicos","Texto de documentos cargados (no subir datos personales)","Medio"],chat:["Chat de campaña","Preguntas del equipo con el contexto agregado de la campaña","Metas y datos agregados (sin personas)","Medio"],chatbot:["Chatbot ciudadano","Responde a ciudadanos solo con respuestas aprobadas","Preguntas de ciudadanos; respuestas aprobadas","Alto"]};
T.IA.on=f=>!!(S.iaF[f]&&S.iaF[f].on);
const puedeIA=()=>["candidato","gerente","juridico"].includes(S.rol);
T.IA.gate=tab=>{if(tab=="gobierno")return vGob();if(tab=="chatbot"&&T.IA.on("chatbot"))return vBot();const f=T.IA.FUN[tab];if(f&&!T.IA.on(tab))return `<div class="card locked" id="ia-locked" style="margin-top:12px"><h2>🔒 ${H(f[0])}: apagada</h2><p class="small">Las funciones de IA vienen <b>apagadas por defecto</b>. Se activan una a una en <b>Gobierno de IA</b>, con una justificación que queda registrada.</p><a class="btn pri" href="#/IA?gobierno">Ir a Gobierno de IA</a></div>`;return null};
function vGob(){const p=S.iaProv;return `<div class="grid g2" style="margin-top:12px"><div class="card"><h2>Proveedor de IA</h2><div class="list small"><div class="row b"><span>Proveedor</span><b>Google Gemini API (plan de pago) vía servidor de ${H(C.marca)}</b></div><div class="row b"><span>Ubicación del procesamiento</span><b>EE. UU. (por verificar)</b></div><div class="row b"><span>Encargo / transmisión de datos</span><b>Contrato de transmisión (por firmar)</b></div><div class="row b"><span>Nunca se envían</span><b>Cédulas, teléfonos, afinidad política ni aportantes</b></div></div>
 <label class="ck" style="margin-top:8px"><input type="checkbox" id="gp-ok" ${p.acepta?"checked":""} ${puedeIA()?"":"disabled"}><span> Declaro que el proveedor configurado <b>no entrena sus modelos con los datos de la campaña</b> y que su uso está documentado como encargo o transmisión (Ley 1581). El plan gratuito de Gemini no cumple esta condición.</span></label>${p.acepta?`<p class="chip ok">✓ Declarado por ${H(p.por)} · ${T.fechaHora(p.t)}</p>`:""}
 <h2 style="margin-top:12px">Reglas de uso</h2><ul class="small"><li>La IA propone, una persona decide: nada se publica ni se envía sin revisión humana registrada.</li><li>Todo contenido lleva el aviso visible «Hecho con IA».</li><li>Prohibidos los deepfakes de rivales, funcionarios, periodistas y personas fallecidas (Ley 2502 de 2025).</li><li>No se pegan bases de simpatizantes en herramientas de IA externas.</li><li>Sin segmentar por opinión política ni datos sensibles sin autorización.</li></ul></div>
 <div class="card"><h2>Registro de funciones de IA</h2><div class="list">${Object.entries(T.IA.FUN).map(([k,[n,fin,dat,r]])=>{const f=S.iaF[k];return `<div class="item" style="cursor:default;align-items:flex-start"><span style="flex:1"><b>${H(n)}</b> <span class="chip ${f.on?"ok":""}">${f.on?"Activa":"Apagada"}</span> <span class="chip ${r=="Alto"?"wa":""}">Riesgo ${r}</span><br><span class="muted small">${H(fin)} · Datos: ${H(dat)} · Modelo probabilístico · Supervisión humana obligatoria</span>${f.on?`<br><span class="small">Justificación: «${H(f.just)}» · ${H(f.por)}</span>`:""}</span>${puedeIA()?(f.on?`<button class="btn sm" data-iaoff="${k}" type="button">Apagar</button>`:`<button class="btn sm pri" data-iaon="${k}" type="button">Activar</button>`):""}</div>`}).join("")}</div><p class="muted small">Las guardas (difamación, deepfakes, datos sensibles, art. 35) son reglas fijas, no IA, y no se pueden apagar.</p></div></div>`}
T.onClick("[data-iaon]",t=>{const k=t.dataset.iaon;if(!S.iaProv.acepta){T.toast("Primero declara que el proveedor no entrena con los datos de la campaña");return}const m=T.modal(`<h2>Activar: ${H(T.IA.FUN[k][0])}</h2><label for="ij-txt">Justificación (necesidad y proporcionalidad)</label><textarea id="ij-txt" rows="3" placeholder="¿Para qué la necesita la campaña y cómo se supervisa?"></textarea><button class="btn pri" id="ij-ok" type="button" style="width:100%;margin-top:10px">Activar</button>`);
 m.querySelector("#ij-ok").onclick=()=>{const j=m.querySelector("#ij-txt").value.trim();if(j.length<30){T.toast("La justificación debe tener al menos 30 caracteres");return}S.iaF[k]={on:true,just:j,por:T.ROLES[S.rol].n,t:new Date().toISOString()};T.save();T.log("ia.activar",T.IA.FUN[k][0]+" · "+j);m.remove();T.toast("✓ Función activada y registrada");T.rerender()}});
T.onClick("[data-iaoff]",t=>{const k=t.dataset.iaoff;S.iaF[k]={on:false};T.save();T.log("ia.apagar",T.IA.FUN[k][0]);T.toast("Función apagada");T.rerender()});
const norm=s=>String(s).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
const OFIC=/(donde voto|puesto de votacion|mesa de votacion|inscrib\w* (la )?cedula|jurado|registraduria|que documento|como voto|tarjeton)/;
T.chatbotResponder=q=>{const n=norm(q);if(OFIC.test(n))return{a:"Para eso la fuente oficial es la Registraduría Nacional del Estado Civil: consulta tu lugar de votación y requisitos en www.registraduria.gov.co (enlace por verificar). Yo no doy información oficial del proceso electoral.",f:"Remisión a fuente oficial"};
 let best=null,sc=0;S.faq.forEach(f=>{const s=f.k.filter(k=>n.includes(norm(k))).length;if(s>sc){sc=s;best=f}});
 if(best&&best.estado=="aprobada")return{a:best.a,f:"Respuesta aprobada por "+best.por};return{a:"No tengo una respuesta aprobada para eso. Dejé tu pregunta para que te responda una persona del equipo.",f:"Sin respuesta aprobada · pasa a una persona",pend:true}};
function vBot(){const ed=["candidato","gerente","juridico"].includes(S.rol);return `<div class="grid g2" style="margin-top:12px"><div class="card"><div class="legal small" id="cb-id">🤖 <b>Soy un asistente automático</b> de la campaña de ${H(C.candidato)}. <b>No soy una persona.</b> Solo respondo con información aprobada por el equipo.</div><div class="chat" id="cb-log" style="margin-top:10px">${S.cb.map(m=>`<div class="msg ${m.r}">${H(m.t)}${m.f?`<br><span class="muted small">${H(m.f)}</span>`:""}</div>`).join("")}</div><div class="row" style="margin-top:10px"><input type="text" id="cb-in" placeholder="Escribe tu pregunta" aria-label="Pregunta al chatbot" style="flex:1"><button class="btn pri" id="cb-go" type="button">Enviar</button></div><button class="btn sm" id="cb-clr" type="button" style="margin-top:8px">Borrar conversación</button></div>
 <div class="card"><h2>Respuestas aprobadas</h2><div class="list small">${S.faq.map(f=>`<div class="row b"><span>${H(f.q)}<br><span class="muted">${H(f.a.slice(0,90))}</span></span>${f.estado=="aprobada"?'<span class="chip ok">Aprobada</span>':ed?`<button class="btn sm" data-faqok="${f.id}" type="button">Aprobar</button>`:'<span class="chip wa">Borrador</span>'}</div>`).join("")}</div><h2 style="margin-top:12px">Preguntas para una persona (${S.cbPend.length})</h2><div class="list small">${S.cbPend.map(p=>`<span>• ${H(p)}</span>`).join("")||'<span class="muted">Ninguna</span>'}</div><p class="muted small">El chatbot no usa IA generativa para responder: solo devuelve textos aprobados. Las conversaciones se guardan con retención limitada.</p></div></div>`}
T.onClick("[data-faqok]",t=>{const f=S.faq.find(x=>x.id==t.dataset.faqok);f.estado="aprobada";f.por=T.ROLES[S.rol].n;T.save();T.log("chatbot.aprobar",f.q);T.rerender()});
T.IA.after3=tab=>{if(tab=="chatbot"&&T.IA.on("chatbot")){const go=()=>{const q=T.$("#cb-in").value.trim();if(!q)return;const r=T.chatbotResponder(q);S.cb.push({r:"u",t:q},{r:"a",t:r.a,f:r.f});if(r.pend)S.cbPend.push(q);T.save();T.log("chatbot.respuesta",r.f);T.rerender();const l=T.$("#cb-log");l.scrollTop=l.scrollHeight};T.$("#cb-go").onclick=go;T.$("#cb-in").onkeydown=e=>{if(e.key=="Enter")go()};T.$("#cb-clr").onclick=()=>{S.cb=[];T.save();T.rerender()};return true}
 if(tab=="gobierno"){const g=T.$("#gp-ok");g&&(g.onchange=()=>{S.iaProv=g.checked?{acepta:true,por:T.ROLES[S.rol].n,t:new Date().toISOString()}:{acepta:false};T.save();T.log("ia.proveedor",g.checked?"Declaración de no entrenamiento aceptada":"Declaración retirada");T.rerender()});return true}
 return !!T.IA.gate(tab)};
// Compositor: botón de IA respeta la activación; revisión humana queda en la bitácora
const aCont=T.after.CONTENIDO;T.after.CONTENIDO=()=>{aCont();const b=T.$("#ia-red");if(b&&!T.IA.on("contenido"))b.onclick=()=>T.toast("La IA de contenido está apagada: actívala en Asistente IA → Gobierno de IA")};
// =================== Seguridad: segundo canal ===================
T.segundoCanal=(titulo,detalle,fn)=>{const m=T.modal(`<h2>🔐 Confirmación por segundo canal</h2><p class="small">Orden de alto riesgo: <b>${H(titulo)}</b><br>${H(detalle)}</p><p class="warn small">Confírmala <b>solo en la app</b>, con el código de tu autenticador. Nunca por llamada, audio, WhatsApp o correo: pueden ser deepfakes o suplantaciones.</p><label for="sc-cod">Código de verificación (6 dígitos)</label><input type="text" id="sc-cod" inputmode="numeric" maxlength="6" autocomplete="one-time-code"><p class="muted small">Demo: el código del autenticador es 482917.</p><div class="row" style="margin-top:10px"><button class="btn" id="sc-no" type="button">Cancelar</button><button class="btn pri" id="sc-ok" type="button">Confirmar</button></div>`,{noClose:true});
 m.querySelector("#sc-no").onclick=()=>{T.log("seguridad.cancelado",titulo);m.remove();T.toast("Orden cancelada")};
 m.querySelector("#sc-ok").onclick=()=>{if(m.querySelector("#sc-cod").value.trim()!=="482917"){T.log("seguridad.rechazo","Código incorrecto: "+titulo);T.toast("⛔ Código incorrecto: la orden no se ejecuta");return}T.log("seguridad.segundo_canal","Confirmado en la app por "+T.ROLES[S.rol].n+": "+titulo);m.remove();fn()}};
const fin0=T.V.FINANZAS;T.V.FINANZAS=()=>fin0()+`<div class="grid g2" style="margin-top:14px"><div class="card"><h2>Proveedores y cuentas de pago</h2><div class="list small">${S.proveedores.map(p=>`<div class="row b"><span><b>${H(p.n)}</b><br><span class="muted">${H(p.banco)} · cuenta ${H(p.cuenta)}</span></span><button class="btn sm" data-pcta="${p.id}" type="button">Cambiar cuenta</button></div>`).join("")}</div><p class="muted small">Pagos desde ${T.cop(C.seguridad.umbralPago)} y cambios de cuenta exigen confirmación por segundo canal.</p></div>
 <div class="card"><h2>🎭 Simulacro de suplantación</h2><p class="small">Llega un audio por WhatsApp con la voz de la candidata: <i>«Transfiere ya $8.000.000 a esta cuenta nueva, es urgente»</i>.</p><div class="row" style="flex-wrap:wrap"><button class="btn danger" id="sim-ej" type="button">Ejecutar la orden</button><button class="btn ok" id="sim-rep" type="button">Rechazar y reportar</button></div><p class="muted small">Regla: ninguna orden de pago o cambio crítico se acepta por llamada, audio o chat. Solo cuenta lo confirmado en la app.</p></div></div>`;
T.onClick("[data-pcta]",t=>{const p=S.proveedores.find(x=>x.id==t.dataset.pcta);const m=T.modal(`<h2>Cambiar cuenta · ${H(p.n)}</h2><label for="pc-b">Banco</label><input type="text" id="pc-b" value="${H(p.banco)}"><label for="pc-c">Nueva cuenta</label><input type="text" id="pc-c" inputmode="numeric"><button class="btn pri" id="pc-g" type="button" style="width:100%;margin-top:10px">Solicitar cambio</button>`);
 m.querySelector("#pc-g").onclick=()=>{const c=m.querySelector("#pc-c").value.replace(/\D/g,""),b=m.querySelector("#pc-b").value.trim();if(c.length<6){T.toast("Cuenta inválida");return}m.remove();T.segundoCanal("Cambio de cuenta de "+p.n,b+" · ****"+c.slice(-4),()=>{T.accion("finanzas.proveedor.cuenta",p.n+" → ****"+c.slice(-4),()=>{p.banco=b;p.cuenta="****"+c.slice(-4);T.save()});T.rerender()})}});
T.onClick("#sim-ej",()=>T.segundoCanal("Transferencia urgente de $ 8.000.000","Orden recibida por audio de WhatsApp. No hay ninguna solicitud de la candidata en la app.",()=>{T.toast("Transferencia registrada (simulada)")}));
T.onClick("#sim-rep",()=>{T.log("seguridad.suplantacion","Audio de WhatsApp con voz de la candidata pidiendo transferencia: rechazado y reportado");T.toast("✓ Rechazado y reportado al jurídico. Bien hecho.")});
// =================== Día E: reportes entrantes ===================
T.validaReporte=r=>{if(!r.aut)return[false,"Rechazado: canal no autenticado ("+r.canal+"). Solo cuentan los reportes de testigos autenticados en la app."];if(r.asignada!==r.mesa)return[false,"Rechazado: el testigo no está asignado a la mesa "+r.mesa+"."];if(r.rafaga>5)return[false,"Bloqueado: ráfaga de "+r.rafaga+" reportes en 60 s (posible ataque automatizado). Se avisa a la coordinación."];return[true,"Aceptado: testigo autenticado en su mesa asignada."]};
const diae0=T.V.DIAE;T.V.DIAE=()=>{const h=diae0();if(S.rol=="testigo")return h.replace("</h1>",'</h1><p class="chip ok" style="margin-top:4px">🔐 Sesión autenticada: solo puedes reportar tus mesas asignadas</p>');
 const tabB=`<a class="btn sm ${T.ruta().includes("rep")?"on":""}" href="#/DIAE?rep">🔐 Reportes entrantes</a>`;let o=h.replace(/(<div class="tabs"[^>]*>)/,"$1"+tabB);
 if(T.ruta().includes("rep")){const i=o.indexOf('<div class="card" style="margin-top:12px">'),j=o.indexOf('<p class="legal small" style="margin-top:12px"><b>Preconteo');o=o.slice(0,i)+repView()+o.slice(j);o=o.replace('class="btn sm on" href="#/DIAE"','class="btn sm" href="#/DIAE"')}return o};
function repView(){return `<div class="card" style="margin-top:12px"><h2>Reportes entrantes</h2><div class="tw"><table><tr><th>Hora</th><th>Canal</th><th>Remitente</th><th>Mesa</th><th>Contenido</th><th>Decisión</th></tr>${S.reportes.map(r=>{const [ok,msg]=T.validaReporte(r);return `<tr data-rep="${r.id}"><td>${r.hora}</td><td class="small">${H(r.canal)}</td><td class="small">${H(r.de)}</td><td class="small">${H(r.mesa)}</td><td class="small">${H(r.texto)}</td><td><span class="chip ${ok?"ok":"er"}">${ok?"✓":"⛔"}</span> <span class="small">${H(msg)}</span></td></tr>`}).join("")}</table></div><button class="btn pri" id="rp-proc" type="button" style="margin-top:10px">Procesar reportes</button><p class="muted small">El Día E solo cuentan los reportes de testigos autenticados y vinculados a su mesa. Se limita la tasa y se alerta ante ráfagas. Las denuncias de fraude van por reclamación formal con evidencia.</p></div>`}
T.onClick("#rp-proc",()=>{let a=0,r=0;S.reportes.forEach(x=>{const [ok,msg]=T.validaReporte(x);ok?a++:r++;T.log("diae.reporte."+(ok?"aceptado":"rechazado"),x.mesa+" · "+x.canal+" · "+msg)});T.toast(a+" aceptado(s), "+r+" rechazado(s)")});
// =================== Cumplimiento: normas IA y lo que no se hace ===================
const cum0=T.V.CUMPLIMIENTO;T.V.CUMPLIMIENTO=()=>cum0()+`<div class="grid g2" style="margin-top:14px"><div class="card" id="normas-ia"><h2>Normas sobre IA y datos con fines políticos</h2><div class="list small">
<div><b>Ley 2502 de 2025.</b> Agrava la falsedad personal (C.P., art. 296) cuando se suplanta a alguien con IA (deepfake). Vigente desde el 28-jul-2026. Territoria bloquea imágenes, voces y videos sintéticos de personas distintas de la candidata autorizada.</div>
<div><b>Circular Externa SIC 002 de 2026.</b> Datos personales con fines políticos: autorización previa (instr. 2 y 4); nada de bases de terceros, scraping ni grupos sin consentimiento (instr. 5); prohibido inferir la opinión política sin autorización explícita (instr. 7); informar los criterios de segmentación y el uso de IA (instr. 8). Por verificar con el texto oficial.</div>
<div><b>No hay norma electoral específica sobre IA</b> en propaganda (oct-2026). El aviso «Hecho con IA», la prohibición de deepfakes y la revisión humana son un estándar del producto que se revisa antes de 2027.</div>
<div class="muted">Referencias extranjeras solo como buena práctica: Brasil (TSE), Reglamento europeo de IA.</div></div>
<h2 style="margin-top:12px">Controles de IA activos</h2><div class="list small"><span>Funciones de IA activas: <b>${Object.values(S.iaF).filter(f=>f.on).length} de ${Object.keys(S.iaF).length}</b></span><span>Proveedor sin entrenamiento declarado: <b>${S.iaProv.acepta?"sí":"no"}</b></span><span>Revisiones humanas registradas: <b>${S.bit.filter(b=>b.accion=="ia.revision_humana").length}</b></span><span>Bloqueos de deepfake: <b>${S.bit.filter(b=>/deepfake/.test(b.accion)).length}</b></span></div></div>
<div class="card" id="no-hace"><h2>Lo que Territoria no hace</h2><div class="list small">${D3.noIncorporado.map(([a,b])=>`<div>⛔ <b>${H(a)}.</b> <span class="muted">${H(b)}</span></div>`).join("")}</div></div></div>`;
})();
